import{_ as a,o,c as r,a3 as i}from"./chunks/framework.jVlskimI.js";const g=JSON.parse('{"title":"🌍 生存服 · 详细介绍","description":"","frontmatter":{},"headers":[],"relativePath":"Survival.md","filePath":"Survival.md"}'),t={name:"Survival.md"};function e(n,l,s,d,h,u){return o(),r("div",{"data-pagefind-body":!0},l[0]||(l[0]=[i('<h1 id="🌍-生存服-·-详细介绍" tabindex="-1">🌍 生存服 · 详细介绍 <a class="header-anchor" href="#🌍-生存服-·-详细介绍" aria-label="Permalink to &quot;🌍 生存服 · 详细介绍&quot;">​</a></h1><blockquote><p><strong>Inspurs 核心主服 | 原版拓展 · 极致优化 · 纯净生存</strong></p></blockquote><h2 id="🎮-玩法定位" tabindex="-1">🎮 玩法定位 <a class="header-anchor" href="#🎮-玩法定位" aria-label="Permalink to &quot;🎮 玩法定位&quot;">​</a></h2><p>Inspurs 生存服是一个<strong>基于原版生存玩法、进行深度友好拓展</strong>的长期服务器。<br> 我们保留了 Minecraft 最纯粹的探索、建造与生存乐趣，同时通过精心设计的辅助机制，解决基岩版联机常见的痛点。</p><p>无论你是喜欢<strong>钻研生电科技</strong>、<strong>建造宏伟建筑</strong>，还是只想<strong>找个地方安静养老</strong>，这里都能找到属于你的一片天地。</p><h2 id="✨-核心特色" tabindex="-1">✨ 核心特色 <a class="header-anchor" href="#✨-核心特色" aria-label="Permalink to &quot;✨ 核心特色&quot;">​</a></h2><h3 id="🌱-原版体验-无缝拓展" tabindex="-1">🌱 原版体验，无缝拓展 <a class="header-anchor" href="#🌱-原版体验-无缝拓展" aria-label="Permalink to &quot;🌱 原版体验，无缝拓展&quot;">​</a></h3><ul><li>无强制性付费道具，所有功能均可通过游戏内努力获得。</li><li>辅助功能（如传送、领地）以<strong>不破坏平衡</strong>为前提设计。</li></ul><h3 id="⚙️-生电友好-红石无忧" tabindex="-1">⚙️ 生电友好，红石无忧 <a class="header-anchor" href="#⚙️-生电友好-红石无忧" aria-label="Permalink to &quot;⚙️ 生电友好，红石无忧&quot;">​</a></h3><ul><li>服务器对红石机械、生物农场保持高度兼容，模拟距离 <code>8</code> 确保机器稳定运行。</li><li>定期优化区块加载，降低大型机器造成的卡顿影响。</li></ul><h3 id="🏠-领地保护-安心建造" tabindex="-1">🏠 领地保护，安心建造 <a class="header-anchor" href="#🏠-领地保护-安心建造" aria-label="Permalink to &quot;🏠 领地保护，安心建造&quot;">​</a></h3><ul><li>完善的领地系统，保护你的建筑和财产免受他人破坏。</li><li>支持好友共享权限，合作建设更方便。</li></ul><h3 id="💰-玩家经济-自由交易" tabindex="-1">💰 玩家经济，自由交易 <a class="header-anchor" href="#💰-玩家经济-自由交易" aria-label="Permalink to &quot;💰 玩家经济，自由交易&quot;">​</a></h3><ul><li>拥有独立的玩家市场/商店系统，你可以出售自己的物资，或购买急需的物品。</li><li>经济活跃，物价由玩家共同决定。</li></ul><h3 id="🛡️-纯净环境-零容忍反作弊" tabindex="-1">🛡️ 纯净环境，零容忍反作弊 <a class="header-anchor" href="#🛡️-纯净环境-零容忍反作弊" aria-label="Permalink to &quot;🛡️ 纯净环境，零容忍反作弊&quot;">​</a></h3><ul><li>智能反作弊系统全天候监控，杜绝矿透、飞行、杀戮等行为。</li><li>人工巡查 + 玩家举报双保险，维护公平游戏氛围。</li></ul><h2 id="📋-基础规则" tabindex="-1">📋 基础规则 <a class="header-anchor" href="#📋-基础规则" aria-label="Permalink to &quot;📋 基础规则&quot;">​</a></h2><ol><li><strong>尊重他人</strong>：禁止辱骂、人身攻击、恶意引战。</li><li><strong>禁止作弊</strong>：任何形式的作弊（包括脚本、连点器自动化操作）均会导致永久封禁。</li><li><strong>禁止恶意破坏</strong>：未授权情况下破坏他人建筑、偷窃物资将被严肃处理。</li><li><strong>友好利用漏洞</strong>：如发现游戏漏洞或插件问题，请及时向管理员反馈，禁止利用漏洞获利。</li><li><strong>建筑规范</strong>：避免在出生点附近或他人建筑旁建造遮挡物、巨型红石机器以免影响他人体验。</li></ol><blockquote><p>📢 详细规则请加入 QQ 群 <code>657209397</code></p></blockquote><h2 id="🧭-新手引导" tabindex="-1">🧭 新手引导 <a class="header-anchor" href="#🧭-新手引导" aria-label="Permalink to &quot;🧭 新手引导&quot;">​</a></h2><p>初次进入生存服，建议按以下步骤快速上手：</p><ol><li><p><strong>绑定白名单</strong><br> 首次进入根据提示绑定账号，后续进服自动识别。</p></li><li><p><strong>寻找安家点</strong><br> 在主城周边或远方探索，找到一个心仪的位置作为你的基地。</p></li><li><p><strong>圈地保护</strong><br> 使用 <strong>PLand</strong> 领地插件圈地，保护你的劳动成果。具体操作可查看群文件或询问群友。</p></li><li><p><strong>开启你的旅程</strong><br> 挖矿、建造、交易、探索……整个世界的可能性由你书写！</p></li></ol><h2 id="🔧-游戏内功能入口" tabindex="-1">🔧 游戏内功能入口 <a class="header-anchor" href="#🔧-游戏内功能入口" aria-label="Permalink to &quot;🔧 游戏内功能入口&quot;">​</a></h2><p>Inspurs 生存服为玩家精心设计了 <strong>图形化菜单 UI</strong>，绝大多数常用功能都可以通过一个指令呼出菜单并轻松操作，无需记忆繁杂指令。</p><ul><li><strong>主菜单指令</strong>：<code>/cd</code></li><li><strong>菜单包含功能</strong>（持续更新）： <ul><li>🏠 领地管理</li><li>📦 玩家市场/商店</li><li>💰 经济与转账</li><li>🌍 传送与家园</li><li>⚙️ 个人设置</li></ul></li></ul><blockquote><p>✨ <strong>小贴士</strong>：进入游戏后直接输入 <code>/cd</code>或者<code>右键钟表菜单</code>你就能看到所有可用功能的可视化界面。从此告别指令表，点点鼠标/屏幕就能畅玩！</p></blockquote><h2 id="🌟-未来规划" tabindex="-1">🌟 未来规划 <a class="header-anchor" href="#🌟-未来规划" aria-label="Permalink to &quot;🌟 未来规划&quot;">​</a></h2><p>生存服将持续迭代更新，计划中的内容包含：</p><ul><li>[×] 更多趣味世界事件（如随机血月、宝藏猎人）</li><li>[×] 玩家等级称号系统</li><li>[×] 社区建筑竞赛与奖励</li><li>[×] 针对基岩版新版本的快速适配</li></ul><p>你的每一个建议，都可能成为下一项更新内容！</p><blockquote><p>✨ <strong>小贴士</strong>：咕咕咕咕~</p></blockquote><h2 id="💬-反馈与交流" tabindex="-1">💬 反馈与交流 <a class="header-anchor" href="#💬-反馈与交流" aria-label="Permalink to &quot;💬 反馈与交流&quot;">​</a></h2><ul><li><strong>QQ 群</strong>：<code>657209397</code></li><li>在群里可以： <ul><li>提交 BUG 或建议</li><li>寻找队友/交易伙伴</li><li>参与服务器活动投票</li><li>与服主和玩家们闲聊</li></ul></li></ul><hr><p><em>Inspurs 生存服 · 始于热爱，忠于玩家体验</em><br><em>期待你的加入，一起书写我们的故事。</em></p>',35)]))}const p=a(t,[["render",e]]);export{g as __pageData,p as default};
